def latticeDilationEquiv (L : Submodule ℤ ℍ) (a : ℝ) (ha : a ≠ 0) :
    L ≃ₗ[ℤ] dilatedLattice L a ha :=
  ZLattice.comap_equiv ℝ L (realDilation a ha).symm.toLinearEquiv

