def kernelNumerator (ν : Fin 3 → ℕ) (k : Fin 4) :
    RealPoly4 :=
  numeratorJet (spatialDerivativeList ν) k

def realCoord (i : Fin 4) : ℍ →L[ℝ] ℝ :=
  (ContinuousLinearMap.proj i).comp
      coordinateBasis.equivFunL.toContinuousLinearMap

def harmonicNumerator (ν : Fin 3 → ℕ) (q : ℍ) : ℍ :=
  ∑ k : Fin 4, polyEval (kernelNumerator ν k) q •
      coordinateBasis k
